import{_ as t,o as a,c as r,a2 as o}from"./chunks/framework.DdtnLau3.js";const u=JSON.parse('{"title":"Service Specification","description":"","frontmatter":{},"headers":[],"relativePath":"spec/service.md","filePath":"spec/service.md"}'),i={name:"spec/service.md"};function n(c,e,s,d,p,l){return a(),r("div",null,[...e[0]||(e[0]=[o('<h1 id="service-specification" tabindex="-1">Service Specification <a class="header-anchor" href="#service-specification" aria-label="Permalink to &quot;Service Specification&quot;">​</a></h1><h2 id="current-behavior" tabindex="-1">Current behavior <a class="header-anchor" href="#current-behavior" aria-label="Permalink to &quot;Current behavior&quot;">​</a></h2><p>A Service is a persisted, Work-scoped application definition. Core creates its container, manages enabled state, inspects readiness, and reconciles lifecycle after recovery.</p><p>The Harness reaches Core through the native <code>piwork-service-mcp</code> process and authenticated Work-scoped control channel. Core enforces ownership, runtime identity, policy, and quota. User applications run on the Work&#39;s private Docker network.</p><h2 id="current-definition-and-tools" tabindex="-1">Current definition and tools <a class="header-anchor" href="#current-definition-and-tools" aria-label="Permalink to &quot;Current definition and tools&quot;">​</a></h2><p>Service creation declares a name, image, command, optional environment, working directory, workspace access, ports, readiness, and resource settings. The exact required fields, defaults, and nested limits are in the shipped <a href="https://github.com/pphboy/piwork/blob/main/internal/servicemcp/tools.json" target="_blank" rel="noreferrer">MCP JSON schemas</a>. Use those schemas rather than a guessed Docker Compose document.</p><p>The current MCP surface contains:</p><table tabindex="0"><thead><tr><th>Tools</th><th>Purpose</th></tr></thead><tbody><tr><td><code>deployment_context</code></td><td>Inspect available deployment context.</td></tr><tr><td><code>service_create</code>, <code>service_update</code></td><td>Declare or change a Service.</td></tr><tr><td><code>service_list</code>, <code>service_get</code>, <code>service_logs</code></td><td>Observe Services.</td></tr><tr><td><code>service_start</code>, <code>service_stop</code>, <code>service_restart</code>, <code>service_retry</code>, <code>service_remove</code></td><td>Manage lifecycle.</td></tr><tr><td><code>operation_get</code></td><td>Inspect an accepted operation.</td></tr></tbody></table><p>Tools are projected to the model under the <code>work-services__</code> namespace, subject to tool policy. Mutation requests require an <code>idempotencyKey</code> and return durable acceptance before the operation finishes. Retain the original Service and Operation IDs to inspect results.</p><h2 id="network-and-storage" tabindex="-1">Network and storage <a class="header-anchor" href="#network-and-storage" aria-label="Permalink to &quot;Network and storage&quot;">​</a></h2><p>Declared HTTP ports can be opened through Desktop&#39;s authenticated application gateway. Containers do not receive arbitrary public host-port exposure. Platform credentials remain separate from application cookies and authorization.</p><p>Services can mount the shared workspace at <code>/var/data/workspace</code> when authorized. Store portable application data in managed storage. Removing a Service retains shared workspace files; those files are not treated as disposable container data.</p><p>Stopping a Work retains Service definitions and enabled intent. Starting the Work restores enabled Services. Stopping an individual Service disables its intent until explicitly started again.</p><h2 id="experimental-and-future-direction" tabindex="-1">Experimental and future direction <a class="header-anchor" href="#experimental-and-future-direction" aria-label="Permalink to &quot;Experimental and future direction&quot;">​</a></h2><p>The experimental brain&#39;s Service capability contract adds structured observation, state versions, action identity, and verification. Applications must implement that contract to participate. An arbitrary web application is not automatically a verified-action endpoint.</p><p>Broader categories of capabilities may fit the product&#39;s Service concept over time. The current runtime contract is a managed application container.</p><p>See the authoritative <a href="https://github.com/pphboy/piwork/blob/main/openspec/specs/work-services/spec.md" target="_blank" rel="noreferrer">work-services spec</a>, <a href="https://github.com/pphboy/piwork/blob/main/docs/service-mcp.md" target="_blank" rel="noreferrer">Service MCP guide</a>, and <a href="https://github.com/pphboy/piwork/blob/main/docs/service-access.md" target="_blank" rel="noreferrer">application access guide</a>.</p>',17)])])}const m=t(i,[["render",n]]);export{u as __pageData,m as default};
